function demo(){let w=blank();w.profile={name:'FIELD / Demo',role:'CEO',industry:t('پلتفرم فروش آنلاین','Online commerce platform'),size:'50',problem:exampleData.direction.outcome};for(const e of D.entries)w.assets[e.id]={data:{...(exampleData[e.id]||{})},saved:false,status:'illustrative',knowledge:'known',recordOwner:exampleData[e.id]?.owner||t('مسئول برنامهٔ AI','AI Program Lead'),sourceEvidence:t('مثال آموزشی از GODAE؛ فرضی','GODAE learning example; illustrative'),revisions:[]};w.issues=D.company.portfolio.map(x=>({...x,hours:'',evidence:t('فرض آموزشی؛ نیازمند شواهد شرکت','Illustrative; actual company evidence required')}));w.selectedIssue='AI-101';const people={sponsor:t('مینا · مدیرعامل','Mina · CEO'),lead:t('آرش · مسئول برنامه','Arash · Program lead'),owner:t('سارا · مسئول رشد','Sara · Growth lead'),analyst:t('علی · تحلیلگر','Ali · Analyst'),developer:t('نیما · توسعه‌دهنده','Nima · Developer'),champion:t('رها · چمپیون تیم','Raha · Team champion'),reviewer:t('لیلا · بازبین','Leila · Reviewer'),user:t('تیم اجرای کمپین','Campaign operators')};D.roles.forEach(r=>w.roles[r.id]={name:people[r.id],authority:r.responsibility});w.roadmap=D.company.roadmap.map(x=>({...x}));D.readiness.forEach(r=>w.readiness[r.id]={state:'partial',evidence:t('نمونهٔ فرضی؛ نیاز به شواهد شرکت','Illustrative; requires company evidence'),owner:w.roles.lead.name});return w;}
