 $$('[data-edit-role],[data-edit-roadmap],[data-edit-issue],[data-edit-connection]',root).forEach(x=>{const span=document.createElement('div');span.className=x.className;span.innerHTML=x.innerHTML;span.style.cssText=x.style.cssText;$$('[data-icon=edit]',span).forEach(y=>y.remove());x.replaceWith(span);});
 $$('[data-fsg-part]',root).forEach(b=>{if(b.closest('.app-chrome')){b.remove();return;}const part=b.dataset.fsgPart;b.dataset.guideFsg=part;delete b.dataset.fsgPart;b.setAttribute('aria-label',t('توضیح و مثالِ ','Explanation and example: ')+part);b.insertAdjacentHTML('beforeend',ic('arrow'));});
