const readinessLevels=[1,1,0,1,0,0,1,1];
function readiness(){return `${head('claude-code',t('آمادگی برای تحول AI / یک مثال قابل‌تغییر','AI transformation readiness / Explore an example'))}<div class="readiness-intro"><span>${ic('cog')}${t('روی یک وضعیت در هر ردیف کلیک کن.','Select a state in each row.')}</span><small>${t('مثال آموزشی؛ اطلاعات شرکتت ذخیره نمی‌شه.','Learning example; no company data is saved.')}</small></div><div class="readiness-layout"><div class="readiness-matrix" role="group" aria-label="${t('ماتریس آمادگی','Readiness matrix')}"><div class="readiness-matrix-head"><strong>${t('بُعد','Dimension')}</strong><span>${t('در شروع مسیر','Getting started')}</span><span>${t('در حال شکل‌گیری','Building capability')}</span><span>${t('آمادهٔ یک شروع جدی','Established')}</span></div>${readinessDimensions.map(([name,states],i)=>`<div class="readiness-dimension"><strong><bdi>${n(i+1)}</bdi>${name}</strong>${states.map((label,j)=>`<button data-ready-row="${i}" data-ready-level="${j}" aria-pressed="${readinessLevels[i]===j}"><span class="ready-choice-dot"></span><span>${label}</span></button>`).join('')}</div>`).join('')}</div><aside class="readiness-result" data-readiness-result></aside></div><footer class="app-caption">${t('اقتباس از ۸ بُعد Claude با سه سطح ساده. این نمایش، آزمون استاندارد یا نمرهٔ آمادگی شرکت نیست.','Adapted from Claude’s eight dimensions into three levels. This demonstration is not a validated company readiness score.')}</footer>`;}
function refreshReadiness(){const weak=readinessLevels.map((x,i)=>x===0?i:-1).filter(i=>i>=0),established=readinessLevels.filter(x=>x===2).length;$$('[data-ready-row]').forEach(x=>x.setAttribute('aria-pressed',String(readinessLevels[+x.dataset.readyRow]===+x.dataset.readyLevel)));$$('[data-readiness-result]').forEach(x=>{x.innerHTML=`<span class="readiness-meter" style="--ready:${readinessLevels.reduce((a,b)=>a+b,0)/16*100}%"><b>${n(established)}<small>/ ${n(8)}</small></b><span>${t('بُعد با شرایط روشن','dimensions established')}</span></span><h3>${weak.length?t('قبل از ساخت، این‌ها رو روشن کنیم.','Resolve these before building.'):t('حالا یک فرصت محدود رو بررسی کنیم.','Now inspect a bounded opportunity.')}</h3><ul>${(weak.length?weak:[0,6]).map(i=>`<li>${ic(weak.length?'search':'check')}<span>${readinessDimensions[i][0]}</span></li>`).join('')}</ul><p>${weak.length?t('یک مسئول برای فاصله‌های این مثال مشخص می‌کنیم؛ بعد دامنهٔ پایلوت رو با ظرفیت واقعی تنظیم می‌کنیم.','Assign ownership for these gaps, then match the pilot scope to real capacity.'):t('هدف، معیار نتیجه و مرزها رو قبل از شروع پایلوت ثبت می‌کنیم.','Record the outcome, measure and boundaries before the pilot.')}</p><small>${t('قدم بعد: استراتژی برنامه','Next: Strategy')}</small>`;});}

function connections(){return `${head('google-drive',t('یک ابزار؛ یک اتصال با حد اختیار روشن','One tool. One scoped connection.'))}<div class="connection-example"><div>${logo('google-drive')}<strong>FIELD-01 / approved-assets</strong><span>${badge(t('فقط خواندن','READ ONLY'),'success')}</span></div><span class="connection-wire">${ic('arrow')}</span><div>${logo('codex')}<strong>${t('دستیارِ پایلوت','Pilot assistant')}</strong><span>${badge(t('پیش‌نویس داخلی','INTERNAL DRAFT'))}</span></div><span class="connection-wire">${ic('arrow')}</span><div>${logo('gmail')}<strong>${t('ارسال به مشتری','Customer delivery')}</strong><span>${badge(t('نیازمند تأیید انسان','HUMAN APPROVAL'),'warning')}</span></div></div><footer class="app-caption">${t('MCP یا API وسیلهٔ اتصاله. محدودهٔ داده و اختیارِ انجام کار رو شما تعیین می‌کنین. نمونهٔ آموزشی؛ حسابی متصل نیست.','MCP or API supplies the connection. Your organization defines resources and action authority. Learning example; no accounts are connected.')}</footer>`;}
