function chapterPreview(){const views={direction:charter,opportunities:()=>backlog(false),ownership:()=>team(),boundaries:permissions,roadmap,goal:pilot,observe:()=>brief(false),decide:paired,act:pilotRun,evaluate:decision};return `<div class="chapter-example-caption"><span>${ic('file')}<bdi>${esc(entry?.destination||'strategy/transformation.json')}</bdi></span><small>${t('خروجی این بخش · با دادهٔ نمونه','THIS CHAPTER’S OUTPUT · ILLUSTRATIVE DATA')}</small></div>${(views[entry?.id]||(()=>scaleView(entry?.id)))()}`;}
function openingCase(id){if(!openingCases[id])return scaleView(id,true);const [icons,labels,result,finalIcon]=openingCases[id];return `<div class="opening-case" data-case="${id}"><div class="case-meta"><span class="case-id">FIELD-01</span><span>${t('یک کمپین؛ مثال مشترک این راهنما','One campaign. The shared example throughout this guide.')}</span>${badge(t('نمونهٔ آموزشی','ILLUSTRATIVE'))}</div><div class="case-chain">${labels.map((label,i)=>`<article><span class="input-plaque">${ic(icons[i])}</span><small>0${i+1}</small><h3>${label}</h3>${i<2?`<span class="case-connector">${ic('arrow')}</span>`:''}</article>`).join('')}</div><div class="case-conclusion"><span class="input-plaque">${ic(finalIcon)}</span><strong>${result}</strong></div></div>`;}
function dependencies(){return `${head('jira',t('اول پیش‌نیاز، بعد ساخت','Dependencies before deadlines'))}<div class="dependency-chain">${W().roadmap.map((x,i)=>`<section><small>${t('مرحله','STAGE')} ${n(i+1)}</small><span class="input-plaque">${ic(['target','cog','rocket'][i])}</span><h3>${esc(x.title)}</h3><p>${esc(x.owner)}</p><bdi>${i===0?'Strategy + brief':i===1?'Execution + evals':'Pilot + decision'}</bdi>${i<2?`<span class="case-connector">${ic('arrow')}</span>`:''}</section>`).join('')}</div>`;}
function responsibilityMap(){return `${head('notion',t('چه کسی تصمیم می‌گیره؛ چه کسی تحویل می‌ده؟','Who decides? Who delivers?'))}<div class="table-scroll"><table class="responsibility-table"><thead><tr>${[t('مسئولیت','Responsibility'),t('مسئولِ اصلی','Accountable person'),t('خروجی ملموس','Deliverable')].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${[['sponsor',t('هدف، بودجه و رفع مانع','Direction, funding and escalation'),t('هدف و محدودهٔ برنامه','Program outcome and scope')],['lead',t('هماهنگی بین تیم‌ها','Coordinate the program'),t('بک‌لاگ و نقشهٔ راه','Backlog + roadmap')],['analyst',t('شناخت کار و تعریف پذیرش','Observe and define acceptance'),'workflow-acceptance.md'],['developer',t('ساخت اجرا و ارزیابی','Build execution and evaluation'),'workflow.spec.json + evaluations/'],['owner',t('پذیرش نتیجهٔ کسب‌وکار','Accept the business outcome'),'results.json'],['champion',t('تست روزمره و بازخورد','Daily testing and feedback'),t('بازخورد استفادهٔ واقعی','Real-use feedback')],['reviewer',t('بررسی ریسک و اختیار','Review risk and authority'),t('تصمیم تأییدِ نسخهٔ دقیق','Exact-version approval')],['user',t('استفاده در کار واقعی','Use it in real work'),t('شواهد نتیجه و مشکل‌ها','Outcome evidence and issues')]].map(([role,job,asset])=>`<tr><th>${job}</th><td>${esc(member(role))}</td><td><bdi>${asset}</bdi></td></tr>`).join('')}</tbody></table></div>`;}

