function decision(){return `${head('jira',t('نتیجهٔ ارزیابی → کار بعدی تیم','Evaluation findings → the team’s next work'))}<div class="decision-board"><header><span>${badge(t('اصلاح قبل از گسترش','ITERATE BEFORE EXPANSION'),'warning')}</span><h2>${t('می‌دونیم کجا گیر کرده؛ حالا همان‌جا رو اصلاح کنیم.','We know where it falls short. Fix those points next.')}</h2></header><div>${[[t('کیفیت ۳٫۶؛ هدف ۴','Quality 3.6; target 4'),t('لیلا + نیما','Leila + Nima'),t('متن ایمیل ضعیفه. نمونهٔ خوب برند رو به پرامپت اضافه کن، همان Dataset رو دوباره اجرا کن و با نسخهٔ قبلی مقایسه کن.','Email tone is weak. Add approved brand examples to the prompt, rerun the same Dataset and compare versions.'),'langfuse'],[t('استفاده ۲۰٪؛ هدف ۶۰٪','Use 20%; target 60%'),t('رها + تیم اجرا','Raha + operators'),t('کنار کاربر یک کمپین رو انجام بده. ببین کجا به روش قبلی برمی‌گرده و همان مانع رو برطرف کن.','Complete one campaign alongside an operator. Find where they revert to the old process and remove that obstacle.'),'slack'],[t('زمان ۳٫۵ روز؛ هدف ۳','Lead time 3.5 days; target 3'),t('علی + سارا','Ali + Sara'),t('زمان انتظار فایل و تأیید رو جدا ببین. کندی تولید متن با کندی تحویل بین آدم‌ها یکی نیست.','Separate file and approval waiting time. Slow generation and slow handoffs need different fixes.'),'jira']].map(([gap,owner,action,tool])=>`<article>${logo(tool)}<strong>${gap}</strong><small>${owner}</small><p>${action}</p></article>`).join('')}</div><footer>${ic('target')}${t('سارا تصمیم می‌گیره: یک دور اصلاح؛ فعلاً تیم یا کانال جدید اضافه نمی‌کنیم.','Sara’s decision: one correction cycle; no new team or channel yet.')}</footer></div>${exampleNote()}`;}
function evaluationReport(){return `${head('notion',t('گزارش پایلوت / FIELD-01','Pilot review / FIELD-01'))}<article class="worked-document"><div class="document-breadcrumb">FIELD / Growth / Pilot review</div><h2>${t('کمپین سریع‌تر شده؛ هنوز آمادهٔ گسترش نیست.','Campaigns are faster. Expansion is not justified yet.')}</h2><div class="document-properties"><span>${t('مسئول: سارا','Owner: Sara')}</span><span>G2 / AI-101</span><span>v0.3</span>${badge(t('اصلاح','ITERATE'),'warning')}</div><h3>${t('چه دیدیم؟','What did we observe?')}</h3><p>${t('۵ روز به ۳٫۵ روز رسید. کیفیت ۳٫۶ از ۵ و استفاده ۲۰٪ بود؛ هر دو از هدف پایین‌ترن. نتیجهٔ نرخ تبدیل هنوز نداریم.','Lead time fell from 5 to 3.5 days. Quality was 3.6/5 and eligible-work usage 20%; both miss their targets. Conversion remains unmeasured.')}</p><h3>${t('چه چیزی رو عوض می‌کنیم؟','What changes next?')}</h3><ol><li>${t('لیلا و نیما: نمونه‌های برند، اصلاح پرامپت و مقایسهٔ دوباره در Langfuse.','Leila and Nima: brand examples, prompt revision and a new Langfuse comparison.')}</li><li>${t('رها: یک جلسهٔ کار واقعی برای پیدا کردن مانع استفاده.','Raha: a real-work session to find the adoption barrier.')}</li><li>${t('علی: زمان انتظار تأیید و نتیجهٔ کمپین رو اندازه می‌گیره.','Ali: measure approval waiting time and the campaign outcome.')}</li></ol><h3>${t('شرط بررسی گسترش','Before reviewing expansion')}</h3><p>${t('کیفیت و هدف کسب‌وکار به حد توافق‌شده برسن؛ استفادهٔ واقعی، هزینه و مسئول پشتیبانی هم روشن باشن.','Meet the agreed quality and business goals, and establish real use, full cost and support ownership.')}</p></article>${exampleNote()}`;}
const scalePlans={standardize:[t('روشِ جواب‌داده رو قابل‌تکرار کن.','Make the proven method repeatable.'),['workflows/campaign/workflow.spec.json','skills/campaign/SKILL.md','evaluations/campaign/cases.json'],[t('نسخه و مالک مشخص','Version and owner'),t('روش و مثال قابل‌استفادهٔ دوباره','Reusable procedure and examples'),t('تستِ جلوگیری از پسرفت','Regression checks')]],enable:[t('کاربر باید بدونه کِی و چطور ازش استفاده کنه.','People need to know when and how to use it.'),['people/team-playbook.md','learning/worked-example.md','operations/feedback.json'],[t('روش کار و تحویل خطا','Working procedure and escalation'),t('یک نمونه از اول تا آخر','One end-to-end worked example'),t('بازخوردِ کار واقعی','Feedback from real use')]],operate:[t('بعد از انتشار، مسئولیت تازه شروع می‌شه.','Operating responsibility starts at release.'),['operations/owners.json','operations/review.json','operations/incidents.json'],[t('مسئول پشتیبانی و توقف','Support and stop owner'),t('کیفیت، هزینه و پذیرش','Quality, cost and adoption'),t('خطا، بازیابی و یادگیری','Incidents, recovery and learning')]],expand:[t('پایلوت دوم باید از اولی یاد بگیره.','The second pilot should learn from the first.'),['strategy/transformation.json#opportunities','strategy/transformation.json#roadmap','strategy/transformation.json#boundaries'],[t('فرصت بعد: ارزش بالا، اختلال کم','Next opportunity: high value, low disruption'),t('ظرفیت و وابستگیِ واقعی','Real capacity and dependencies'),t('بازبینی اختیار برای محدودهٔ جدید','Reassess authority for the new scope')]]};
