'scale-learning':['notion',t('یک جلسه، یک کار واقعی','One session, one real job'),[[t('چمپیون','Champion'),member('champion'),t('بریف و منبع رو با کاربر آماده می‌کنه','Prepare the brief and source with the user')],[t('کاربر','User'),member('user'),t('اجرا، بازبینی و ارجاع خطا رو تجربه می‌کنه','Try execution, review and escalation')],[t('مسئول کسب‌وکار','Business owner'),member('owner'),t('خروجی رو با معیار واقعی بررسی می‌کنه','Review against the acceptance criteria')]]],
