function drawFlowBranches(){
 for(const canvas of $$('.flow-canvas')){
  const step=canvas.querySelector('[data-flow-step="3"]'),target=canvas.querySelector('.flow-side-note');if(!step||!target||!target.getClientRects().length||!canvas.getClientRects().length)continue;
  let svg=canvas.querySelector('.flow-branch-svg');if(!svg){svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('flow-branch-svg');svg.setAttribute('aria-hidden','true');canvas.prepend(svg);}
  const root=canvas.getBoundingClientRect(),a=step.getBoundingClientRect(),b=target.getBoundingClientRect(),rtl=getComputedStyle(canvas).direction==='rtl',x=(rtl?a.left:a.right)-root.left,y=a.top+a.height/2-root.top,tx=(rtl?b.right:b.left)-root.left,ty=b.top+b.height/2-root.top,m=(x+tx)/2,sign=rtl?-1:1;
  svg.setAttribute('viewBox',`0 0 ${root.width} ${root.height}`);svg.innerHTML=`<path d="M${x} ${y} H${m} V${ty} H${tx-sign*5}"/><path class="flow-branch-tip" d="M${tx} ${ty} L${tx-sign*6} ${ty-3} L${tx-sign*6} ${ty+3}Z"/>`;
 }
}
